<?php declare(strict_types=1);
ini_set('zend.exception_ignore_args','1');
require dirname(__DIR__).'/native/bootstrap.php';

use Kulturhus\Native\Cms\{Articles, Conflict, NewsPolicy, Pages, PageCopies, PageTrash, PublicationSchedule, Schema};
use Kulturhus\Native\Shared\{Access, Db};
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Web\{Articles as ArticleView, Manager};
use Kulturhus\Native\Web\Settings\NewsPolicyPanel;
use Kulturhus\Native\Web\Website\PageEditor;

$checks=[];
function check(bool $ok,string $label): void {global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks[]=$label;}
function rejects(callable $f,string $label): void {try{$f();}catch(DomainException|InvalidArgumentException|Conflict $e){check(true,$label);return;}throw new RuntimeException('FAIL: accepted '.$label);}
$db=TestSupport::db();$actors=TestSupport::seed($db);Schema::install($db);Schema::install($db);
$access=new Access($db,'admin');$second=new Access($db,'editor');$reader=new Access($db,'reader');
Db::run($db,"INSERT INTO native_grants VALUES('editor','website','publish')");
$articles=new Articles($db,$access);$other=new Articles($db,$second);$pages=new Pages($db,$access);$policy=new NewsPolicy($db,$access);
$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/review-media';
$view=new ArticleView($db,$access,$root,'csrf');$otherView=new ArticleView($db,$second,$root,'csrf');
$standard=$pages->save(['title'=>'Normale Inhaltsseite','slug'=>'ordinary']);
$legacy=$articles->save(['title'=>'Vorhandener Beitrag','slug'=>'aktuelles/legacy','news_date'=>'2050-02-03','body'=>'Genauer alter Inhalt']);
$legacy=$articles->publish($legacy['id'],$legacy['version']);
$original=json_encode($pages->publicPage($legacy['slug']),JSON_THROW_ON_ERROR);$generation=$pages->generation();
check($policy->get()['version']===0&&!$policy->get()['enabled'],'policy starts optional with legacy publication unchanged');
check($policy->save(false,0)['version']===0&&$policy->history()===[],'unchanged choice creates no artificial policy revision');
rejects(fn()=>(new NewsPolicy($db,$reader))->save(true,0),'reader cannot enable policy');
rejects(fn()=>(new NewsPolicy($db,$second))->save(true,0),'publisher cannot manage club policy');
foreach(['1',1,null,[],true]as$value)if($value!==true)rejects(fn()=>$policy->save($value,0),'strict boolean policy rejects '.get_debug_type($value));
$state=$policy->save(true,0);check($state['enabled']&&$state['version']===1,'administrator enables versioned club rule');
check(json_encode($pages->publicPage($legacy['slug']),JSON_THROW_ON_ERROR)===$original&&$pages->generation()===$generation,'private policy preserves exact public original and generation');
rejects(fn()=>$policy->save(false,0),'stale policy form cannot disable rule');
rejects(fn()=>$articles->publish($legacy['id'],$legacy['version']),'legacy draft now needs explicit second-person approval');
$standard=$pages->publish($standard['id'],$standard['version']);check($standard['published_revision']!==null,'ordinary pages do not require news approval');
$legacy=$articles->review($legacy['id'],'review',$legacy['version']);
rejects(fn()=>$articles->review($legacy['id'],'approved',$legacy['version']),'author cannot approve after changing their own review state');
$html=$view->manager($legacy['id']);
check(str_contains($html,'Wartet auf Freigabe durch eine andere Person.')&&!str_contains($html,'value="approved"'),'author sees waiting state without self-approval control');
check((bool)preg_match('~<button[^>]*disabled[^>]*>Beitrag veröffentlichen~',$html),'publisher author receives disabled publication control');
check((bool)preg_match('~<button[^>]*disabled[^>]*>Veröffentlichung planen~',$html),'planning control explains missing approval and stays disabled');
check(str_contains($otherView->manager($legacy['id']),'value="approved"'),'other publisher receives real approval form');
$legacy=$other->review($legacy['id'],'approved',$legacy['version']);$approvalRevision=$legacy['version'];
$proof=$policy->state($legacy['id'],$legacy);
check($proof['valid']&&$proof['author']==='admin'&&$proof['approval']['reviewer_id']==='editor','approval records exact author and different reviewer');
check(!array_key_exists('news_approval',$legacy),'private approval proof does not change public payload shape');
$proofBytes=Db::run($db,'SELECT * FROM khcms_news_approvals WHERE page_id=?',[$legacy['id']])->fetchAll();
rejects(fn()=>$other->review($legacy['id'],'approved',$legacy['version']),'repeated valid approval does not create extra decision');
$legacy=$articles->publish($legacy['id'],$legacy['version']);
check($pages->publicPage($legacy['slug'])['body']==='Genauer alter Inhalt','author can publish exact separately approved content');
check($policy->state($legacy['id'],$legacy)['valid'],'publication metadata does not invalidate canonical content approval');
$public=json_encode($pages->publicPage($legacy['slug']),JSON_THROW_ON_ERROR);
$legacy=$articles->save(['id'=>$legacy['id'],'body'=>'Privater neuer Inhalt','news_review'=>'approved','news_approval'=>['reviewer_id'=>'editor']],$legacy['version']);
check($legacy['news_review']==='draft'&&!$policy->state($legacy['id'],$legacy)['valid'],'content edit and forged proof cannot preserve approval');
check(json_encode($pages->publicPage($legacy['slug']),JSON_THROW_ON_ERROR)===$public,'editing preserves exact public original');
rejects(fn()=>$articles->publish($legacy['id'],$legacy['version']),'edited content cannot publish with old approval');
$clock=time()+100;$schedule=new PublicationSchedule($db,$access,static fn()=>$clock);
rejects(fn()=>$schedule->plan($legacy['id'],$legacy['version'],$clock+60),'edited content cannot be scheduled with old approval');
$legacy=$other->review($legacy['id'],'approved',$legacy['version']);
$job=$schedule->plan($legacy['id'],$legacy['version'],$clock+60);
$snapshot=Db::run($db,'SELECT snapshot_json FROM khcms_publication_schedule WHERE id=?',[$job['id']])->fetchColumn();
check($snapshot===Db::run($db,'SELECT draft_json FROM khcms_pages WHERE id=?',[$legacy['id']])->fetchColumn(),'planned approval retains exact original payload bytes');
$state=$policy->save(false,$state['version']);$state=$policy->save(true,$state['version']);
check(!$policy->state($legacy['id'],$legacy)['valid'],'changed club policy invalidates old approvals without mutating content');
check(str_contains($otherView->manager($legacy['id']),'Erneut freigeben'),'already approved state has clear renewal control for current rule');
PublicationSchedule::runDue($db,fn()=>$access,50,$clock+61);
check($schedule->forPage($legacy['id'])['status']==='blocked','worker rechecks changed policy instead of publishing old plan');
check(json_encode($pages->publicPage($legacy['slug']),JSON_THROW_ON_ERROR)===$public,'blocked worker preserves exact public original');
$legacy=$other->review($legacy['id'],'approved',$legacy['version']);
$job=$schedule->plan($legacy['id'],$legacy['version'],$clock+120);
PublicationSchedule::runDue($db,fn()=>$access,50,$clock+121);
$legacy=$articles->get($legacy['id']);
check($schedule->forPage($legacy['id'])['status']==='published'&&$pages->publicPage($legacy['slug'])['body']==='Privater neuer Inhalt','worker publishes exact renewed four-eyes original');
check($proofBytes===Db::run($db,'SELECT * FROM khcms_news_approvals WHERE page_id=? AND revision=?',[$legacy['id'],$approvalRevision])->fetchAll(),'all subsequent operations retain immutable first approval proof');
$copy=(new PageCopies($db,$access))->create($legacy['id'],$legacy['version'],['title'=>'Neue private Kopie','slug'=>'aktuelles/copy','basis'=>'published']);
check($copy['news_review']==='draft'&&!$policy->state($copy['id'],$copy)['valid'],'copy has its own content author and no inherited approval');
rejects(fn()=>$articles->publish($copy['id'],$copy['version']),'published-original copy cannot bypass new approval');
$legacy=$articles->restore($legacy['id'],$approvalRevision,$legacy['version']);
check($legacy['news_review']==='draft'&&!$policy->state($legacy['id'],$legacy)['valid'],'restore cannot reuse an immutable historical approval');
$legacy=$other->review($legacy['id'],'approved',$legacy['version']);
$trash=new PageTrash($db,$access);$legacy=$trash->move($legacy['id'],$legacy['version']);
$legacy=$trash->restore($legacy['id'],$legacy['version']);
check($legacy['news_review']==='draft'&&!$policy->state($legacy['id'],$legacy)['valid'],'trash return requires fresh approval');
$legacy=$other->review($legacy['id'],'approved',$legacy['version']);
$legacy=$articles->archive($legacy['id'],$legacy['version']);$legacy=$articles->unarchive($legacy['id'],$legacy['version']);
check($legacy['news_review']==='draft'&&!$policy->state($legacy['id'],$legacy)['valid'],'archive return requires fresh approval');
$legacy=$other->review($legacy['id'],'review',$legacy['version']);
rejects(fn()=>$articles->review($legacy['id'],'approved',$legacy['version']),'other review-state change never changes actual author');
Db::run($db,"DELETE FROM native_grants WHERE actor_id='editor' AND module='website' AND capability='publish'");
rejects(fn()=>$other->review($legacy['id'],'approved',$legacy['version']),'revoked current publisher cannot approve');
Db::run($db,"INSERT INTO native_grants VALUES('editor','website','publish')");
Db::run($db,"UPDATE native_users SET active=0 WHERE id='editor'");
rejects(fn()=>$other->review($legacy['id'],'approved',$legacy['version']),'disabled second person cannot approve');
Db::run($db,"UPDATE native_users SET active=1 WHERE id='editor'");
try{(new Articles($db,new Access($db,'outsider')))->review($legacy['id'],'approved',$legacy['version']);throw new LogicException('foreign approval');}catch(RuntimeException $e){check($e->getMessage()==='Seite nicht gefunden.','foreign club cannot access original approval');}
check(!(new NewsPolicy($db,new Access($db,'outsider')))->get()['enabled'],'another club retains independent default policy');
$html=(new PageEditor($db,$access,$root,'csrf'))->manager($legacy['id']);check(str_contains($html,'data-four-eyes="required"')&&(bool)preg_match('~<button[^>]*disabled[^>]*>Veröffentlichen~',$html),'general editor shares actual policy and disabled publication');
$manager=new Manager($db,$access,$root,'csrf');
$post=['csrf'=>'csrf','operation'=>'news-policy','version'=>(string)$state['version'],'news_policy_present'=>'1'];
foreach([['csrf'=>'wrong'],['news_policy_present'=>[]],['news_four_eyes'=>['1']],['version'=>['1']]]as$bad)rejects(fn()=>$manager->action('settings',array_replace($post,$bad),[]),'HTTP policy form rejects malformed or expired fields');
$manager->action('settings',$post,[]);check(!$policy->get()['enabled'],'real settings action disables optional rule');
$legacy=$articles->publish($legacy['id'],$legacy['version']);check($legacy['published_revision']!==null,'optional mode retains original editorial publication behavior');
check(count($policy->history())===4,'policy changes retain exact bounded audit history');
$race=$articles->save(['title'=>'Gleichzeitige Vereinsregel','slug'=>'aktuelles/race','news_date'=>'2050-02-03','body'=>'Unverändertes eigenes Original']);
$db->beginTransaction();
check((int)Db::run($db,'SELECT four_eyes FROM khcms_news_policy WHERE club_id=?',[$access->club()])->fetchColumn()===0,'outer repeatable-read transaction starts before new rule');
$current=TestSupport::db();$currentPolicy=new NewsPolicy($current,new Access($current,'admin'));$currentPolicy->save(true,$currentPolicy->get()['version']);
rejects(fn()=>$articles->publish($race['id'],$race['version']),'publication sees rule committed after an older repeatable-read snapshot');
$db->rollBack();
check($pages->get($race['id'])['published_revision']===null,'rejected concurrent-policy publication leaves no public original');
$race=$other->review($race['id'],'approved',$race['version']);
$db->beginTransaction();Db::run($db,'SELECT COUNT(*) FROM khcms_revisions')->fetchColumn();
$changed=(new Articles($current,new Access($current,'editor')))->save(['id'=>$race['id'],'body'=>'Tatsächlich durch die Prüferin bearbeitet'],$race['version']);
rejects(fn()=>$other->review($race['id'],'approved',$changed['version']),'older transaction sees current content author and cannot self-approve');
$db->rollBack();
$race=$articles->review($race['id'],'approved',$changed['version']);
check($policy->state($race['id'],$race)['approval']['reviewer_id']==='admin','original author can review a later independently edited original');
$publishOnly=$articles->save(['title'=>'Prüfung ohne Bearbeitungsrecht','slug'=>'aktuelles/publish-only','news_date'=>'2050-02-03','body'=>'Genauer vom Autor gespeicherter Inhalt']);
Db::run($db,"INSERT INTO native_grants VALUES('reader','website','publish')");
$publishOnlyView=new ArticleView($db,$reader,$root,'csrf');
$readOnlyHtml=$publishOnlyView->manager($publishOnly['id']);
check(str_contains($readOnlyHtml,'value="approved"')&&!str_contains($readOnlyHtml,'value="article-save"'),'publisher without editing rights can read and independently approve exact content');
$publishOnlyView->action(['csrf'=>'csrf','operation'=>'article-review','id'=>$publishOnly['id'],'version'=>(string)$publishOnly['version'],'review_status'=>'approved']);
$publishOnly=$articles->get($publishOnly['id']);
check($policy->state($publishOnly['id'],$publishOnly)['valid']&&$policy->state($publishOnly['id'],$publishOnly)['approval']['reviewer_id']==='reader','real article HTTP adapter accepts approval with publish rights alone');
rejects(fn()=>$publishOnlyView->action(['csrf'=>'csrf','operation'=>'article-review','id'=>$publishOnly['id'],'version'=>(string)$publishOnly['version'],'review_status'=>'review']),'approval authority does not grant content editing or other editorial decisions');
echo json_encode(['passed'=>count($checks),'checks'=>$checks,'live_transport'=>false],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)."\n";
